states_in_africa = {
	input = game:all_states
	operators = {
		limit = {
			is_on_continent = africa
		}
	}
	name = COLLECTION_STATES_IN_AFRICA
}

COG_set_up_african_resistance_states = {

	hidden_effect = {
		for_each_scope_loop = {
			array = global.countries 
			IF = {
				limit = {
					# Find countries with cores in africa that do not already exist as free or puppeted nations
					exists = no 
					any_state = { 
						is_core_of = PREV
						is_on_continent = africa 
						OWNER = {
							NOT = { is_in_faction_with = ROOT }
							NOT = { tag = ROOT }
						}
					}
				}

array = global.countries
break = break
limit = {
    is_dynamic_country = no
    exists = no
    any_state = {
        is_core_of = PREV   # Is core of the currently-checked country
    }
}
random_core_state = {
    transfer_state_to = PREV    # Transfers to the currently-selected country.
}
